verus! {
    /// Given a slice `numbers` and a 32‐bit integer `delim`,
    /// return a fresh Vec which intersperses `delim` between
    /// every pair of consecutive elements of `numbers`.
    ///
    /// If `numbers.len() == 0`, the result is empty.
    /// Otherwise, if `n = numbers.len() > 0`, the result has
    /// length `2*n - 1`, the even indices 0,2,4,… hold exactly
    /// the original elements in order, and the odd indices
    /// 1,3,5,… all hold `delim`.
    fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
        ensures numbers.len() == 0 ==> res.len() == 0
        ensures numbers.len() >  0 ==> res.len() == 2 * numbers.len() - 1
        ensures forall |i: usize| i < numbers.len() ==>
                   res[2 * i] == numbers[i]
        ensures forall |i: usize| i + 1 < numbers.len() ==>
                   res[2 * i + 1] == delim
        decreases numbers.len()
    {
        let n = numbers.len();
        let mut out: Vec<i32> = Vec::with_capacity(if n == 0 { 0 } else { 2 * n - 1 });
        let mut i: usize = 0;

        // We loop over i = 0..n, maintaining the following invariants:
        while i < n {
            invariant!(i <= n);
            // out.len() == 0 if i==0, else 2*i-1
            invariant!(out.len() == if i == 0 { 0 } else { 2 * i - 1 });
            // the even positions hold the first i numbers
            invariant!(forall(|k: usize| k < i ==> out[2 * k] == numbers[k]));
            // the odd positions (below 2*i-1) hold delim
            invariant!(forall(|k: usize| k + 1 < i ==> out[2 * k + 1] == delim));
            decreases!(n - i);

            // push the next element
            out.push(numbers[i]);
            // if this is not the last element, follow it by delim
            if i + 1 < n {
                out.push(delim);
            }
            i += 1;
        }

        // Final sanity checks to match the post‐conditions
        assert!(n == 0 ==> out.len() == 0);
        assert!(n > 0 ==> out.len() == 2 * n - 1);

        out
    }
}